// GENERATED by scripts/sync-skill.mjs from prototype/motion.js. Edit the prototype, not this copy.
const TAU = Math.PI * 2;
function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}
function lerp(a, b, t) {
  return a + (b - a) * t;
}
/** Semi-implicit Euler spring, sub-stepped (prototype/springs.js). */
function stepSpring(x, v, target, stiffness, damping, dt, maxStep = 1 / 120) {
  let px = x;
  let pv = v;
  let remaining = Math.max(0, dt);
  while (remaining > 1e-9) {
    const h = Math.min(maxStep, remaining);
    pv += (-stiffness * (px - target) - damping * pv) * h;
    px += pv * h;
    remaining -= h;
  }
  return { x: px, v: pv };
}
/** Crossfade weight of the current clip: { prev, fade, fadeDur } (prototype/statemachine.js). */
function currentWeight(sm) {
  if (!sm.prev || sm.fadeDur <= 0) return 1;
  const x = clamp(sm.fade / sm.fadeDur, 0, 1);
  return x * x * (3 - 2 * x);
}
// Anti-puppet motion layers. Pure: no DOM, deterministic given inputs.
//
// Each function attacks one specific "puppet" tell found in the frame review:
//   stepOverlap      rigid, in-sync limbs   -> lag/drag/overshoot per bone (successive breaking of joints)
//   idleNoiseLayer   frozen, mirrored idle  -> low-frequency non-repeating noise + asymmetric contrapposto
//   breath*          dead torso             -> breathing whose rate follows exertion
//   stepHold         60 fps "tweened" look  -> anime timing: hold poses on 2s/3s
//   stepTurn         instant mirror flip    -> a head-first turn (features slide across the head volume)
//   handShapeFor     same ball hand always  -> pose-specific drawn part swaps

// ---------------------------------------------------------------- overlap / follow-through

/**
 * Per-bone rotation springs. k = stiffness (1/s^2), zeta = damping ratio
 * (< 1 overshoots), gx/gy = how strongly a change of the body's velocity
 * (px/s, facing-relative) kicks the bone,
 * max = largest allowed deviation from the animated target (rad). A kick of g * dv
 * gives roughly g * dv radians of peak deflection (velocity is scaled by sqrt(k)).
 * Distal bones are softer than proximal ones so motion ripples outward.
 */
export const OVERLAP_SPEC = {
  chest: { k: 600, zeta: 0.75, gx: 0.00008, gy: -0.00008, max: 0.2 },
  head: { k: 320, zeta: 0.5, gx: -0.0003, gy: -0.00028, max: 0.4 },
  upperArmF: { k: 380, zeta: 0.55, gx: 0.0007, gy: 0, max: 0.6 },
  upperArmB: { k: 380, zeta: 0.55, gx: 0.0007, gy: 0, max: 0.6 },
  foreArmF: { k: 230, zeta: 0.45, gx: 0.0006, gy: 0.0002, max: 0.7 },
  foreArmB: { k: 230, zeta: 0.45, gx: 0.0006, gy: 0.0002, max: 0.7 },
  handF: { k: 160, zeta: 0.4, gx: 0.0012, gy: -0.0006, max: 0.9 },
  handB: { k: 160, zeta: 0.4, gx: 0.0012, gy: -0.0006, max: 0.9 },
};

export function createOverlap() {
  return {};
}

/**
 * Run the animated pose's rotations through the springs.
 * dv = { x, y }: change of body velocity since the last step (facing-relative, px/s).
 * Returns { state, pose } (new objects; inputs untouched).
 */
export function stepOverlap(state, pose, dt, dv = { x: 0, y: 0 }, spec = OVERLAP_SPEC, amount = 1) {
  const nextState = {};
  const out = {};
  for (const [k, v] of Object.entries(pose || {})) out[k] = { ...v };
  for (const [bone, s] of Object.entries(spec)) {
    const target = out[bone]?.rot ?? 0;
    const prev = state[bone] ?? { x: target, v: 0 };
    const kick = (s.gx * (dv.x || 0) + s.gy * (dv.y || 0)) * amount;
    const r = stepSpring(prev.x, prev.v + kick * Math.sqrt(s.k), target, s.k, 2 * s.zeta * Math.sqrt(s.k), dt);
    const x = clamp(r.x, target - s.max, target + s.max);
    const vel = x === r.x ? r.v : 0;
    nextState[bone] = { x, v: vel };
    out[bone] = { ...(out[bone] || {}), rot: lerp(target, x, clamp(amount, 0, 1)) };
  }
  return { state: nextState, pose: out };
}

// ---------------------------------------------------------------- idle life

/** Smooth, non-repeating noise in about [-1, 1]: three incommensurate sines with seeded phases. */
export function smoothNoise(t, seed) {
  const p1 = ((seed * 9301 + 49297) % 233280) / 233280;
  const p2 = ((seed * 4561 + 12345) % 104729) / 104729;
  const p3 = ((seed * 7919 + 2718) % 65521) / 65521;
  return (
    0.55 * Math.sin(t * 0.73 + p1 * TAU) +
    0.3 * Math.sin(t * 1.618 + p2 * TAU) +
    0.15 * Math.sin(t * 2.97 + p3 * TAU)
  );
}

/** Constant asymmetric offsets: weight on the back leg, one arm more bent (contrapposto). */
export const IDLE_ASYM = {
  hips: { x: -0.8 },
  spine: { rot: -0.03 },
  chest: { rot: 0.04 },
  head: { rot: 0.06 },
  thighB: { rot: 0.07 },
  upperArmF: { rot: 0.1 },
  foreArmF: { rot: -0.35 },
  upperArmB: { rot: -0.05 },
  foreArmB: { rot: -0.1 },
};

/** Additive idle layer: noise (amplitudes in rad / px) + asymmetry. Multiply by the idle weight. */
export function idleNoiseLayer(t, seed = 1) {
  const n = (i) => smoothNoise(t, seed * 31 + i);
  const layer = {
    hips: { x: 0.9 * n(0) + IDLE_ASYM.hips.x },
    spine: { rot: 0.03 * n(1) + IDLE_ASYM.spine.rot },
    chest: { rot: 0.025 * n(2) + IDLE_ASYM.chest.rot },
    head: { rot: 0.07 * n(3) + IDLE_ASYM.head.rot },
    thighB: { rot: IDLE_ASYM.thighB.rot },
    upperArmF: { rot: 0.07 * n(4) + IDLE_ASYM.upperArmF.rot },
    foreArmF: { rot: 0.09 * n(5) + IDLE_ASYM.foreArmF.rot },
    upperArmB: { rot: 0.05 * n(6) + IDLE_ASYM.upperArmB.rot },
    foreArmB: { rot: 0.06 * n(7) + IDLE_ASYM.foreArmB.rot },
  };
  return layer;
}

/** Run asymmetry: the far arm swings less and hangs back, the head leads a little. */
export const RUN_ASYM = {
  head: { rot: -0.06 },
  upperArmB: { rot: 0.18 },
  foreArmB: { rot: 0.15 },
  upperArmF: { rot: -0.05 },
};

/** Weight of a named state in the current crossfade (0..1). */
export function stateWeight(sm, name) {
  const w = currentWeight(sm);
  return (sm.state === name ? w : 0) + (sm.prev === name ? 1 - w : 0);
}

/** Multiply every rot/x/y channel of a layer by w. */
export function scaleLayer(layer, w) {
  const out = {};
  for (const [bone, ch] of Object.entries(layer)) {
    const o = {};
    for (const c of ['rot', 'x', 'y']) if (ch[c] !== undefined) o[c] = ch[c] * w;
    for (const c of ['sx', 'sy']) if (ch[c] !== undefined) o[c] = lerp(1, ch[c], w);
    out[bone] = o;
  }
  return out;
}

// ---------------------------------------------------------------- breathing

/** Exertion 0..1: builds while running/jumping, decays slowly at rest. */
export function stepExertion(e, active, dt) {
  return clamp(active ? e + dt * 0.22 : e - dt * 0.06, 0, 1);
}

/** Breath phase advance; rate goes from ~0.3 Hz (calm) to ~0.9 Hz (winded). Returns new phase. */
export function stepBreath(phase, exertion, dt) {
  return (phase + dt * TAU * lerp(0.3, 0.9, clamp(exertion, 0, 1))) % (TAU * 1000);
}

/** Breathing pose layer from phase + exertion. Inhale lifts the chest and shoulders. */
export function breathLayer(phase, exertion = 0) {
  const b = Math.sin(phase);
  const amp = lerp(1, 1.8, clamp(exertion, 0, 1));
  return {
    chest: { rot: -0.012 * b * amp },
    upperArmF: { y: -0.45 * b * amp },
    upperArmB: { y: -0.45 * b * amp },
    head: { rot: -0.01 * b * amp },
  };
}

/** Torso width multiplier for the breath (applied to the chest part of the torso outline). */
export function breathChest(phase, exertion = 0) {
  return 0.03 * lerp(1, 1.8, clamp(exertion, 0, 1)) * (0.5 + 0.5 * Math.sin(phase));
}

// ---------------------------------------------------------------- anime timing

/** Hold state for posing on 2s/3s: { acc } seconds accumulated since the last shown pose. */
export function createHold() {
  return { acc: Infinity };
}

/**
 * Advance the hold. fps = pose rate (12 = "on 2s" at 24 fps, 8 = "on 3s"); 0/falsy = every frame.
 * Returns { hold, tick } where tick = true when a new pose should be shown this frame.
 */
export function stepHold(hold, dt, fps) {
  if (!fps || fps <= 0) return { hold: { acc: 0 }, tick: true };
  const step = 1 / fps;
  const acc = hold.acc + dt;
  if (acc >= step) return { hold: { acc: acc >= 2 * step ? 0 : acc - step }, tick: true };
  return { hold: { acc }, tick: false };
}

// ---------------------------------------------------------------- turning

/**
 * Head-first turn. When facing flips, `kick` jumps to 1 and decays; while it is
 * high the face is drawn front-on (features slid toward the head centre) and the
 * body is briefly narrowed, so the flip reads as a turn instead of a mirror pop.
 * Returns { facing, kick }.
 */
export function stepTurn(state, facing, dt, rate = 7) {
  const kick = facing !== state.facing ? 1 : state.kick * Math.exp(-rate * dt);
  return { facing, kick: kick < 1e-3 ? 0 : kick };
}

/**
 * Yaw of the face in -1..1 used for feature parallax.
 * +1 = toward full profile (features slide to the front edge), -1 = toward the camera.
 * Running leans toward profile, idle opens to the camera, looking behind turns toward camera.
 */
export function faceYaw({ speed = 0, lookBack = 0, turnKick = 0, noise = 0 }) {
  const base = lerp(-0.25, 0.35, clamp(speed / 220, 0, 1));
  return clamp(base - 0.6 * clamp(lookBack, 0, 1) - 1.1 * turnKick + 0.12 * noise, -1, 1);
}

// ---------------------------------------------------------------- drawn swaps

/** Pose-specific hand drawing for a state. side = 'F' | 'B'. */
export function handShapeFor(state, side) {
  switch (state) {
    case 'run':
    case 'charge':
      return 'fist';
    case 'jumpRise':
      return side === 'F' ? 'open' : 'fist';
    case 'fall':
    case 'hurt':
    case 'land':
      return 'open';
    default:
      return 'relaxed';
  }
}

/** Foot drawing by world angle of the foot (rad, 0 = flat, + = toes down when facing right). */
export function footShapeFor(angle, grounded) {
  if (grounded) return 'flat';
  return angle > 0.75 ? 'point' : 'flat';
}
